.fs-testi .eael-testimonial-quote, .fs-testi .eael-testimonial-image { display: none !important; }
/* review on a purple card: white text */
.fs-purple-card .fs-testi .eael-testimonial-content .eael-testimonial-text, .fs-purple-card .fs-testi .eael-testimonial-content .eael-testimonial-user { color: #fff !important; }
.fs-purple-card .fs-testi .eael-testimonial-content .eael-testimonial-user-company, .fs-purple-card .fs-testi .eael-testimonial-user::after { color: rgba(255, 255, 255, .75) !important; }
